
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revm11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revm11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.079315701899828e-01, -2.978255015266923e-01, -2.834053657578735e-01, -2.628888232591272e-01, -2.338080213767624e-01, -1.928779751982685e-01, -1.367592075392781e-01, -6.854601172251186e-02, -1.827228878195086e-02, -1.606197084247296e-02, -1.818157627322427e-02, -5.103956086543453e-02, -4.685356426853850e-02, -3.229345428348432e-02, -1.512545504344042e-02, -7.454852247790015e-03, -1.970903085648676e-02, -1.599575642498450e-02, -4.820900413624213e-03, -6.891236648355417e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


